require"securerandom";require"active_support/core_ext/string/access";module ActionDispatch;class RequestId;def initialize(app,header:)@app=app;@header=header;@env_header="HTTP_#{header.upcase.tr("-","_")}";end;def call(env)req=ActionDispatch::Request.new env;req.request_id=make_request_id(req.get_header(@env_header));@app.call(env).tap{|_status,headers,_body|headers[@header]=req.request_id};end;private;def make_request_id(request_id)if request_id.presence;request_id.gsub(/[^\w\-@]/,"").first(255);else internal_request_id;end;end;def internal_request_id;SecureRandom.uuid;end;end;end
